  ('PAULA’S CHOICE CLINICAL 0.3% RETINOL + 2% BAKUCHIOL Treatment – 30ml', 'paulas-choice-clinical-03-retinol-2-bakuchiol-treatment-30ml', 'Description This is a mid strength retinol that targets fine lines, wrinkles and gives anti-aging benefits in general. The 2% Bakuchiol amplifies the anti aging benefits derived from the retinol. The peptides stimulates collagen and improves firmness. It’s light weight and absorbs quickly. A great starting point for a beginner.', 9999, 3250, ARRAY['https://cdn.shopify.com/s/files/1/0799/3062/2197/files/IMG-20220725-WA0074.jpg?v=1784364582']::text[], 'serums', 'PAULA''S CHOICE', ARRAY['All'], ARRAY['Anti-Aging'], TRUE, TRUE, TRUE, 4.5, 3),
  ('SOME BY MI – SUPER MATCHA PORE TIGHTENING SERUM 50ML', 'some-by-mi-super-matcha-pore-tightening-serum-50ml', 'DescriptionSOME BY MI – SUPER MATCHA PORE TIGHTENING SERUM 50ML The 93% matcha water purifies, tightens and moisturizes The BHA and PHA dissolves dead skin cells without irritation. Moisturizes with the glacial water, hyaluronic acid and glycerin. Centella asiatica soothes the skin.', 2500, NULL, ARRAY['https://cdn.shopify.com/s/files/1/0799/3062/2197/files/some_by_mi_super_match_pore_tightening_toner_150ml_2.jpg?v=1784364516']::text[], 'serums', 'SOME BY MI', ARRAY['All'], ARRAY[]::text[], TRUE, TRUE, TRUE, 4.6, 17),
  ('SOME BY MI Super matcha pore tightening toner 150ml', 'some-by-mi-super-matcha-pore-tightening-toner-150ml', 'Description Purifies and tightens pores with 83% super matcha water. Dissolves dead skin cells with 5% BHA ingredients. Absorbs excessive sebum , skin impurities with the sebum control powder. Moisturizes with glacial and carbonated water. Calms skin through the Centella and niancinamide.IngredientsCamellia Sinensis Leaf Extract, Propanediol, Salix Alba (Willow) Bark Extract, Niacinamide, 1,2-Hexa', 2300, 600, ARRAY['https://cdn.shopify.com/s/files/1/0799/3062/2197/files/some_by_mi_super_match_pore_tightening_toner_150ml_2.jpg?v=1784364516']::text[], 'toners', 'SOME BY MI', ARRAY['All'], ARRAY[]::text[], TRUE, TRUE, TRUE, 4.0, 49),
  ('Dear Klairs Supple Preparation Unscented Toner 180ml', 'dear-klairs-supple-preparation-unscented-toner-180ml', 'Description This toner preps your skin to absorb serums and other products better. Formulated with ingredients like licorice root extract and aloe leaf extract to calm any irritation. This toner absorbs faster, has a lighter texture, and have absolutely no fragrance.Ingredientslicorice root extract, aloe extract', 2500, 3200, ARRAY['https://cdn.shopify.com/s/files/1/0799/3062/2197/files/IMG-20220725-WA0096.jpg?v=1784364845']::text[], 'toners', 'DEAR KLAIRS', ARRAY['All'], ARRAY[]::text[], TRUE, TRUE, TRUE, 3.9, 49),
  ('iUNIK – Black Snail Restore Serum 50ml', 'iunik-black-snail-restore-serum-50ml', 'Description✨ Enriched with 70% black snail extract and 5 black super food to nourish skin’s natural power to create elastic, smooth and radiant skin.✨ Has Centella Asiatica to alleviate traces of freckles and for a vibrant flawless skin.✨ Niancinamide and adenosine for whitening and wrinkle care.', 2500, 3200, ARRAY['https://images.pexels.com/photos/30229022/pexels-photo-30229022.jpeg?auto=compress&cs=tinysrgb&w=800']::text[], 'serums', 'IUNIK', ARRAY['All'], ARRAY[]::text[], TRUE, TRUE, FALSE, 4.8, 7),
  ('Krave Beauty Oat So Simple Water Cream', 'krave-beauty-oat-so-simple-water-cream', 'DescriptionKrave Beauty Oat So Simple Water CreamOat So Simple Water Cream is a light, refreshing moisturizer designed to provide essential hydration while soothing sensitive skin.Key Features:Minimalist Formula: Contains less than 9 ingredients, focusing on simplicity and effectiveness.Calming Oat Extract: Helps to soothe irritation and balance out the effects of active ingredients in your skinca', 5200, NULL, ARRAY['https://cdn.shopify.com/s/files/1/0799/3062/2197/files/OSS-2_1000x_c50ee106-8c54-4efc-9d36-66357e270ac4.png?v=1784364744']::text[], 'moisturizers', 'KRAVE BEAUTY', ARRAY['All'], ARRAY[]::text[], TRUE, TRUE, TRUE, 4.4, 4),
